-- Combined opening-stock load (RM per-material + WIP/FG + opening date).
-- Generated by scripts/build-rm-opening-sql.mjs. Run once in the PROD Supabase.
-- RM opening matched from the 30/04 stock-take to raw_materials by item_code;
-- unmatched per-group value distributed across the group's remaining SKUs.
BEGIN;
-- 1) Raw-material opening (authoritative full reload for this org).
CREATE TABLE IF NOT EXISTS material_opening_stock (id TEXT PRIMARY KEY, rm_id TEXT NOT NULL, qty DOUBLE PRECISION NOT NULL DEFAULT 0, unit_cost_sen INTEGER NOT NULL DEFAULT 0, as_of_date TEXT NOT NULL, org_id TEXT NOT NULL DEFAULT 'hookka', created_at TEXT, updated_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_mos_key ON material_opening_stock (org_id, rm_id);
DELETE FROM material_opening_stock WHERE org_id = 'hookka';

-- 2) Global cutover date (bare YYYY-MM-DD; the engine regex-validates it).
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

-- 3) WIP / finished-goods opening seed (idempotent re-include).
CREATE TABLE IF NOT EXISTS inventory_opening (id TEXT PRIMARY KEY, org_id TEXT NOT NULL DEFAULT 'hookka', layer TEXT NOT NULL, value_sen INTEGER NOT NULL DEFAULT 0, as_of_date TEXT, updated_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_inventory_opening_key ON inventory_opening (org_id, layer);
ON CONFLICT (org_id, layer) DO UPDATE SET value_sen = EXCLUDED.value_sen, as_of_date = EXCLUDED.as_of_date, updated_at = EXCLUDED.updated_at;
COMMIT;
